class Main {
    // 받은 int의 두 배를 돌려줘요.
    static int twice(int x) {
        // 불릴 때마다 받은 값을 먼저 출력해요.
        System.out.println("twice(" + x + ") 실행");
        return x * 2;
    }

    public static void main(String[] args) {
        // 처음 넘길 값이에요.
        int n = 3;
        System.out.println("시작");
        // 괄호 안 호출이 끝나야 이 줄을 출력할 수 있어요.
        System.out.println("결과: " + twice(n));
    }
}
